-- Internal retained preparation history. Rows never admit or submit provider effects.
CREATE TABLE occ.runtime_preparation_operations (
  operation_ref text PRIMARY KEY,
  preparation_ref text NOT NULL,
  installation_id text NOT NULL,
  namespace_id text NOT NULL,
  agent_id text NOT NULL,
  assignment_ref text NOT NULL,
  local_version bigint NOT NULL,
  operation_kind text NOT NULL,
  child_effect_ref text CONSTRAINT runtime_preparation_child_effect_unique UNIQUE,
  binding_operation_ref text CONSTRAINT runtime_preparation_binding_operation_unique UNIQUE,
  canonical_request text NOT NULL,
  record jsonb NOT NULL,
  CONSTRAINT runtime_preparation_allocation_owner FOREIGN KEY (installation_id,namespace_id,agent_id,assignment_ref)
    REFERENCES occ.runtime_assignment_allocations(installation_id,namespace_id,agent_id,assignment_ref) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT runtime_preparation_version_unique UNIQUE (preparation_ref,local_version),
  CONSTRAINT runtime_preparation_version CHECK (local_version BETWEEN 1 AND 9007199254740991),
  CONSTRAINT runtime_preparation_kind CHECK (operation_kind IN ('retain-plan','retain-child','retain-binding','supersede-plan','close')),
  CONSTRAINT runtime_preparation_request_size CHECK (octet_length(canonical_request) BETWEEN 1 AND 1048576),
  CONSTRAINT runtime_preparation_record_object CHECK (jsonb_typeof(record)='object')
);
--> statement-breakpoint
CREATE FUNCTION occ.runtime_preparation_shape(value jsonb, spec jsonb, depth integer DEFAULT 0) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE item jsonb; property text; child jsonb; scalar text; kind text := spec->>'type';
  source_time timestamptz; received_time timestamptz; valid_time timestamptz; observed_time timestamptz;
  previous_name text; image_name text;
BEGIN
  IF depth>96 OR value IS NULL THEN RETURN false; END IF;
  IF spec ? 'anyOf' THEN
    FOR item IN SELECT jsonb_array_elements(spec->'anyOf') LOOP
      IF occ.runtime_preparation_shape(value,item,depth+1) THEN RETURN true; END IF;
    END LOOP;
    RETURN false;
  END IF;
  IF spec ? 'const' AND value IS DISTINCT FROM spec->'const' THEN RETURN false; END IF;
  IF spec ? 'enum' THEN RETURN EXISTS (SELECT 1 FROM jsonb_array_elements(spec->'enum') AS choices(candidate) WHERE choices.candidate=value); END IF;
  IF kind='object' THEN
    IF jsonb_typeof(value)<>'object' THEN RETURN false; END IF;
    FOR property IN SELECT jsonb_array_elements_text(coalesce(spec->'required','[]'::jsonb)) LOOP
      IF NOT value ? property THEN RETURN false; END IF;
    END LOOP;
    FOR property,child IN SELECT * FROM jsonb_each(value) LOOP
      IF NOT (spec->'properties') ? property OR NOT occ.runtime_preparation_shape(child,spec->'properties'->property,depth+1) THEN RETURN false; END IF;
    END LOOP;
    source_time := coalesce(value->>'providerObservedAt',value->>'verifiedAt',value->>'sourceObservedAt')::timestamptz;
    received_time := (value->>'receivedAt')::timestamptz;
    valid_time := coalesce(value->>'validUntil',value->>'expiresAt')::timestamptz;
    IF source_time>received_time+interval '2 seconds' OR valid_time<source_time OR valid_time>source_time+interval '15 seconds' THEN RETURN false; END IF;
    FOREACH property IN ARRAY ARRAY['policyObservedAt','readinessObservedAt'] LOOP
      observed_time := (value->>property)::timestamptz;
      IF observed_time>source_time+interval '2 seconds' OR valid_time>observed_time+interval '15 seconds' THEN RETURN false; END IF;
    END LOOP;
    IF value ? 'imageDigests' THEN
      FOR item IN SELECT jsonb_array_elements(value->'imageDigests') LOOP
        image_name := item->>'name';
        IF previous_name COLLATE "C">=image_name COLLATE "C" THEN RETURN false; END IF;
        previous_name := image_name;
      END LOOP;
    END IF;
  ELSIF kind='array' THEN
    IF jsonb_typeof(value)<>'array' THEN RETURN false; END IF;
    IF jsonb_array_length(value)<coalesce((spec->>'minItems')::integer,0)
      OR jsonb_array_length(value)>coalesce((spec->>'maxItems')::integer,2147483647) THEN RETURN false; END IF;
    FOR item IN SELECT jsonb_array_elements(value) LOOP
      IF NOT occ.runtime_preparation_shape(item,spec->'items',depth+1) THEN RETURN false; END IF;
    END LOOP;
  ELSIF kind='integer' OR kind='number' THEN
    IF jsonb_typeof(value)<>'number' THEN RETURN false; END IF;
    IF kind='integer' AND value::numeric<>trunc(value::numeric) THEN RETURN false; END IF;
    IF (spec ? 'minimum' AND value::numeric<(spec->>'minimum')::numeric)
      OR (spec ? 'maximum' AND value::numeric>(spec->>'maximum')::numeric) THEN RETURN false; END IF;
  ELSIF kind='string' THEN
    IF jsonb_typeof(value)<>'string' THEN RETURN false; END IF;
    scalar := value#>>'{}';
    IF char_length(scalar)<coalesce((spec->>'minLength')::integer,0)
      OR char_length(scalar)>coalesce((spec->>'maxLength')::integer,2147483647)
      OR (spec ? 'pattern' AND (scalar !~ (spec->>'pattern') OR scalar ~ E'[\\n\\r]')) THEN RETURN false; END IF;
    -- Patterned canonical timestamps must also be real finite calendar instants.
    IF spec->>'pattern' LIKE '%T%Z$' THEN
      IF NOT isfinite(scalar::timestamptz) OR to_char(scalar::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')<>scalar THEN RETURN false; END IF;
    END IF;
  ELSIF kind='null' THEN
    IF value<>'null'::jsonb THEN RETURN false; END IF;
  ELSIF kind='boolean' THEN
    IF jsonb_typeof(value)<>'boolean' THEN RETURN false; END IF;
  ELSE RETURN false;
  END IF;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR invalid_datetime_format OR numeric_value_out_of_range THEN RETURN false;
END;
$$;
