CREATE FUNCTION occ.runtime_preparation_canonical(value jsonb, depth integer DEFAULT 0) RETURNS text
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE result text;
BEGIN
  IF depth>40 THEN RAISE EXCEPTION 'runtime authority canonical depth invalid' USING ERRCODE='23514'; END IF;
  CASE jsonb_typeof(value)
  WHEN 'object' THEN
    SELECT '{'||coalesce(string_agg(to_jsonb(pair.key)::text||':'||occ.runtime_preparation_canonical(pair.item,depth+1),',' ORDER BY pair.key COLLATE "C"),'')||'}'
      INTO result FROM jsonb_each(value) AS pair(key,item);
    RETURN result;
  WHEN 'array' THEN
    SELECT '['||coalesce(string_agg(occ.runtime_preparation_canonical(entry.item,depth+1),',' ORDER BY entry.position),'')||']'
      INTO result FROM jsonb_array_elements(value) WITH ORDINALITY AS entry(item,position);
    RETURN result;
  WHEN 'number' THEN RETURN trunc(value::numeric)::text;
  ELSE RETURN value::text;
  END CASE;
END;
$$;
--> statement-breakpoint
CREATE FUNCTION occ.runtime_preparation_require(condition boolean) RETURNS void LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF condition IS NOT TRUE THEN RAISE EXCEPTION 'runtime preparation invariant invalid' USING ERRCODE='23514'; END IF;
END;
$$;
--> statement-breakpoint
-- JSONB has already rejected invalid Unicode/NUL. This also bounds direct inserts.
CREATE FUNCTION occ.runtime_preparation_data(value jsonb, max_depth integer, depth integer DEFAULT 0) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE item jsonb;
BEGIN
  IF value IS NULL OR depth>max_depth THEN RETURN false; END IF;
  IF jsonb_typeof(value)='object' THEN
    IF (SELECT count(*) FROM jsonb_object_keys(value))>1024 THEN RETURN false; END IF;
    FOR item IN SELECT v FROM jsonb_each(value) e(k,v) LOOP
      IF NOT occ.runtime_preparation_data(item,max_depth,depth+1) THEN RETURN false; END IF;
    END LOOP;
  ELSIF jsonb_typeof(value)='array' THEN
    IF jsonb_array_length(value)>1024 THEN RETURN false; END IF;
    FOR item IN SELECT jsonb_array_elements(value) LOOP
      IF NOT occ.runtime_preparation_data(item,max_depth,depth+1) THEN RETURN false; END IF;
    END LOOP;
  ELSIF jsonb_typeof(value)='number' THEN
    IF value::numeric<>trunc(value::numeric) OR value::numeric<0 OR value::numeric>9007199254740991 THEN RETURN false; END IF;
  END IF;
  RETURN true;
END;
$$;
--> statement-breakpoint
CREATE FUNCTION occ.runtime_preparation_writer_ref(input_value jsonb, scope jsonb, guard jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  RETURN input_value->'closedPlanDigest'=guard->'planDigest' AND input_value->'admittedChildCutoff'=guard->'admittedChildCutoff'
    AND input_value#>'{reservation,scope}'=scope AND input_value#>'{workspaceStore,scope}'=scope
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(input_value->'stores') s WHERE s->'scope' IS DISTINCT FROM scope)
    AND EXISTS (SELECT 1 FROM jsonb_array_elements(input_value->'stores') s WHERE s=input_value->'workspaceStore')
    AND (SELECT count(*)=count(DISTINCT s->'bindingRef') FROM jsonb_array_elements(input_value->'stores') s);
END;
$$;
