  IF NOT (SELECT count(*)=count(DISTINCT t#>'{target,targetRef}') AND count(*)=count(DISTINCT jsonb_build_array(t#>'{target,clusterRef}',t#>'{target,kubernetesNamespaceUid}',t#>'{target,apiKind}',t#>'{target,name}')) FROM jsonb_array_elements(input_value->'targets') t)
