,"minimum":1,"maximum":9007199254740991},"requestedFenceEpoch":{"type":"integer","minimum":1,"maximum":9007199254740991},"responsibility":{"type":"object","required":["responsibilityRef","responsibilityVersion","kind"],"properties":{"responsibilityRef":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"responsibilityVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"kind":{"enum":["preparation","protective-fence","retained-stop"]}},"additionalProperties":false},"gateVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"planRef":{"type":"string","minLength":1,"maxLength":200,"pattern":"^[A-Za-z0-9._:/-]+$"},"planVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"planDigest":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"},"admittedChildCutoff":{"type":"integer","minimum":0,"maximum":9007199254740991}},"additionalProperties":false},"kind":{"type":"string","const":"close"},"expectedVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"reason":{"type":"string","enum":["closed","superseded"]}},"additionalProperties":false}]}$request_schema$::jsonb)
    AND occ.runtime_preparation_shape(NEW.record,$record_schema${"type":"object","required":["schemaVersion","operationRef","preparationRef","target","kind","localVersion","retainedChildSequence","localState","guard","canonicalRequest","requestDigest","attribution"],"properties":{"schemaVersion":{"type":"number","const":1},"operationRef":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"preparationRef":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"target":{"type":"object","required":["installationId","namespaceId","agentId","assignmentRef","revisionId","component","lifecycleGeneration","runtimeGeneration","createEffectRef"],"properties":{"installationId":{"type":"string","pattern":"^ins_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"namespaceId":{"type":"string","pattern":"^ns_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"agentId":{"type":"string","pattern":"^agt_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"assignmentRef":{"type":"object","required":["schemaVersion","id"],"properties":{"schemaVersion":{"type":"number","const":1},"id":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"}},"additionalProperties":false},"revisionId":{"type":"string","pattern":"^rev_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"component":{"enum":["gateway","harness"]},"lifecycleGeneration":{"type":"integer","minimum":1,"maximum":9007199254740991},"runtimeGeneration":{"type":"integer","minimum":1,"maximum":9007199254740991},"createEffectRef":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"}},"additionalProperties":false},"kind":{"type":"string","enum":["retain-plan","retain-child","retain-binding","supersede-plan","close"]},"localVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"retainedChildSequence":{"type":"integer","minimum":0,"maximum":256},"localState":{"type":"string","enum":["open","closed","superseded"]},"guard":{"type":"object","required":["schemaVersion","scope","intentRef","mode","lifecycleGeneration","requestedFenceEpoch","responsibility","gateVersion","planRef","planVersion","planDigest","admittedChildCutoff"],"properties":{"schemaVersion":{"type":"number","const":1},"scope":{"type":"object","required":["installationId","namespaceId","agentId"],"properties":{"installationId":{"type":"string","pattern":"^ins_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"namespaceId":{"type":"string","pattern":"^ns_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"agentId":{"type":"string","pattern":"^agt_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"}}},"intentRef":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"mode":{"enum":["running","stopped","disabled"]},"lifecycleGeneration":{"type":"integer","minimum":1,"maximum":9007199254740991},"requestedFenceEpoch":{"type":"integer","minimum":1,"maximum":9007199254740991},"responsibility":{"type":"object","required":["responsibilityRef","responsibilityVersion","kind"],"properties":{"responsibilityRef":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"},"responsibilityVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"kind":{"enum":["preparation","protective-fence","retained-stop"]}},"additionalProperties":false},"gateVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"planRef":{"type":"string","minLength":1,"maxLength":200,"pattern":"^[A-Za-z0-9._:/-]+$"},"planVersion":{"type":"integer","minimum":1,"maximum":9007199254740991},"planDigest":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"},"admittedChildCutoff":{"type":"integer","minimum":0,"maximum":9007199254740991}},"additionalProperties":false},"canonicalRequest":{"type":"string","minLength":1},"requestDigest":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"},"attribution":{"type":"object","required":["writerRef","recordedAt"],"properties":{"writerRef":{"type":"string","pattern":"^[A-Za-z0-9._:/-]+$","minLength":1,"maxLength":200},"recordedAt":{"type":"string","pattern":"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{3}Z$"}},"additionalProperties":false}},"additionalProperties":false}$record_schema$::jsonb));
  PERFORM occ.runtime_preparation_require(NEW.canonical_request=occ.runtime_preparation_canonical(request));
  kind := request->>'kind'; target := request->'target'; guard := request->'guard';
  scope := jsonb_build_object('installationId',NEW.installation_id,'namespaceId',NEW.namespace_id,'agentId',NEW.agent_id);
  PERFORM occ.runtime_preparation_require(request->>'operationRef'=NEW.operation_ref AND request->>'preparationRef'=NEW.preparation_ref
    AND kind=NEW.operation_kind AND target->>'assignmentRef' IS NOT NULL
    AND guard->'scope'=scope AND guard#>>'{responsibility,kind}'='preparation');
  identities := ARRAY['operation:'||NEW.operation_ref,'preparation:'||NEW.preparation_ref];
  IF kind='retain-child' THEN identities:=array_append(identities,'child:'||(request#>>'{child,effect,effectRef}')); END IF;
  IF kind='retain-binding' THEN identities:=array_append(identities,'binding:'||(request#>>'{operation,operationRef}')); END IF;
  FOR identity IN SELECT identity_value FROM unnest(identities) ids(identity_value) ORDER BY identity_value COLLATE "C" LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('runtime-preparation:'||identity,0));
  END LOOP;
  -- Exact operation/preparation identity locks precede the existing Agent owner lock.
  PERFORM 1 FROM occ.agents WHERE namespace_id=NEW.namespace_id AND id=NEW.agent_id FOR UPDATE;
  SELECT * INTO allocation FROM occ.runtime_assignment_allocations WHERE installation_id=NEW.installation_id
    AND namespace_id=NEW.namespace_id AND agent_id=NEW.agent_id AND assignment_ref=NEW.assignment_ref;
  PERFORM occ.runtime_preparation_require(FOUND);
  PERFORM occ.runtime_preparation_require(target=jsonb_build_object('installationId',allocation.installation_id,'namespaceId',allocation.namespace_id,
    'agentId',allocation.agent_id,'assignmentRef',jsonb_build_object('schemaVersion',1,'id',allocation.assignment_ref),'revisionId',allocation.revision_id,
    'component',allocation.component,'lifecycleGeneration',allocation.lifecycle_generation,'runtimeGeneration',allocation.runtime_generation,'createEffectRef',allocation.create_effect_ref));
  SELECT i.* INTO intent FROM occ.agent_runtime_intent_heads h JOIN occ.agent_runtime_intents i ON i.transition_ref=h.transition_ref
    WHERE h.namespace_id=NEW.namespace_id AND h.agent_id=NEW.agent_id AND i.installation_id=NEW.installation_id;
  PERFORM occ.runtime_preparation_require(FOUND AND request->'currentIntent'=jsonb_build_object('intentRef',intent.transition_ref,'mode',intent.desired_mode,'lifecycleGeneration',intent.generation));
  SELECT record INTO previous FROM occ.runtime_preparation_operations WHERE preparation_ref=NEW.preparation_ref ORDER BY local_version DESC LIMIT 1;
  PERFORM occ.runtime_preparation_require((CASE WHEN previous IS NULL THEN 'null'::jsonb ELSE previous->'localVersion' END)=request->'expectedVersion'
    AND NEW.local_version=coalesce((previous->>'localVersion')::bigint,0)+1);
  IF previous IS NOT NULL THEN
    PERFORM occ.runtime_preparation_require(previous->'target'=target AND previous->'guard'=guard AND previous->>'localState'='open');
    SELECT canonical_request::jsonb INTO original FROM occ.runtime_preparation_operations WHERE preparation_ref=NEW.preparation_ref
      AND operation_kind IN ('retain-plan','supersede-plan') ORDER BY local_version DESC LIMIT 1;
    plan:=original->'plan'; preparation:=original->'preparation';
  END IF;
  selected_guard:=CASE WHEN kind='supersede-plan' THEN request->'nextGuard' ELSE guard END;
  IF kind<>'close' THEN
    PERFORM occ.runtime_preparation_require(intent.desired_mode='running' AND intent.generation=allocation.lifecycle_generation AND intent.revision_id=allocation.revision_id
      AND selected_guard->>'intentRef'=intent.transition_ref AND selected_guard->>'mode'=intent.desired_mode AND (selected_guard->>'lifecycleGeneration')::bigint=intent.generation);
  END IF;
  IF kind IN ('retain-plan','supersede-plan') THEN
    PERFORM occ.runtime_preparation_require(occ.runtime_preparation_plan(request->'plan') AND request#>'{plan,scope}'=scope AND selected_guard->'scope'=scope
      AND selected_guard#>>'{responsibility,kind}'='preparation' AND selected_guard->'planRef'=request#>'{plan,planRef}'
      AND selected_guard->'planVersion'=request#>'{plan,planVersion}' AND selected_guard->'planDigest'=request#>'{plan,planDigest}'
      AND request#>>'{preparation,preparationRef}'=NEW.preparation_ref
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(request#>'{plan,targets}') t WHERE t#>'{target,ownerAssignmentRef}'=target->'assignmentRef' AND t#>'{target,ownerCreateEffectRef}'=target->'createEffectRef'));
    FOR item IN SELECT jsonb_array_elements(request#>'{plan,targets}') LOOP
      PERFORM occ.runtime_preparation_require(EXISTS(SELECT 1 FROM occ.runtime_assignment_allocations a WHERE a.installation_id=NEW.installation_id AND a.namespace_id=NEW.namespace_id
        AND a.agent_id=NEW.agent_id AND a.assignment_ref=item#>>'{target,ownerAssignmentRef,id}' AND a.create_effect_ref=item#>>'{target,ownerCreateEffectRef}'));
    END LOOP;
    IF request#>>'{preparation,kind}'='writable' THEN
      PERFORM occ.runtime_preparation_require(occ.runtime_preparation_writer_ref(request#>'{preparation,priorWriterEvidence}',scope,selected_guard));
    END IF;
  END IF;
  IF kind IN ('retain-plan','retain-binding') THEN
