  END IF;
  IF kind='retain-plan' THEN
    PERFORM occ.runtime_preparation_require(previous IS NULL AND guard->'admittedChildCutoff'='0'::jsonb);
    PERFORM occ.runtime_preparation_require(EXISTS(
      SELECT 1 FROM occ.agent_revision_runtime_admissions a
      JOIN occ.agent_runtime_intents i ON i.transition_ref=a.runtime_transition_ref AND i.namespace_id=a.namespace_id AND i.agent_id=a.agent_id AND i.revision_id=a.revision_id AND i.generation=a.lifecycle_generation
      JOIN occ.agent_revisions r ON r.id=a.revision_id AND r.namespace_id=a.namespace_id AND r.agent_id=a.agent_id
      JOIN occ.audit_events e ON e.id=a.audit_event_id
      JOIN occ.controller_work w ON w.idempotency_key='agent_revision:'||a.revision_id||':reconcile' AND w.namespace_id=a.namespace_id AND w.agent_id=a.agent_id AND w.revision_id=a.revision_id
        AND w.runtime_transition_ref=a.runtime_transition_ref AND w.lifecycle_generation=a.lifecycle_generation AND w.actor_id=i.actor_id AND w.namespace_target IS NULL
      WHERE a.namespace_id=NEW.namespace_id AND a.agent_id=NEW.agent_id AND a.revision_id=allocation.revision_id AND i.installation_id=NEW.installation_id));
  ELSE
    PERFORM occ.runtime_preparation_require(previous IS NOT NULL);
  END IF;
  IF kind='retain-child' THEN
    child:=request->'child'; effect_input:=child->'request'; provider:=child->'providerTarget'; predicate:=child->'predicate';
    PERFORM occ.runtime_preparation_require(occ.runtime_preparation_data(child,32) AND octet_length(occ.runtime_preparation_canonical(child))<=262144
      AND (previous->>'retainedChildSequence')::bigint<256 AND effect_input->'plan'=plan
      AND child->'guard'=guard AND child#>'{effect,target}'=target AND child#>'{effect,responsibility}'=guard->'responsibility'
      AND child->'effect'=effect_input->'effect' AND child->'guard'=effect_input->'gate' AND provider=effect_input->'providerTarget' AND predicate=effect_input->'predicate'
      AND provider->'ownerAssignmentRef'=target->'assignmentRef' AND provider->'ownerCreateEffectRef'=target->'createEffectRef');
    PERFORM occ.runtime_preparation_require(EXISTS(SELECT 1 FROM jsonb_array_elements(plan->'targets') t WHERE t->'target'=provider AND t->'allowedMutations' @> jsonb_build_array(child#>'{effect,effectKind}')));
    IF predicate->>'kind'='expected-object' THEN
      PERFORM occ.runtime_preparation_require(predicate->'ownerAssignmentRef'=target->'assignmentRef' AND predicate->'ownerCreateEffectRef'=target->'createEffectRef'
        AND (predicate->>'fenceEpoch')::bigint<=(guard->>'requestedFenceEpoch')::bigint);
    END IF;
    logical_bytes:=occ.runtime_preparation_canonical(jsonb_set(effect_input,'{effect}',(effect_input->'effect')-'requestDigest'));
    PERFORM occ.runtime_preparation_require(child->>'canonicalRequestJson'=logical_bytes AND octet_length(logical_bytes)<=65536
      AND child->>'requestBytesDigest'='sha256:'||encode(sha256(convert_to(logical_bytes,'UTF8')),'hex')
      AND child#>'{effect,requestDigest}'=child->'requestBytesDigest'
      AND octet_length(request->>'providerWireUtf8') BETWEEN 1 AND 65536
      AND (child#>>'{providerWire,byteLength}')::bigint=octet_length(request->>'providerWireUtf8')
      AND child#>>'{providerWire,bytesDigest}'='sha256:'||encode(sha256(convert_to(request->>'providerWireUtf8','UTF8')),'hex'));
    IF effect_input->>'kind'='create' THEN
      PERFORM occ.runtime_preparation_require(effect_input->'preparation'=preparation AND effect_input->'action'=child#>'{effect,effectKind}'
        AND provider->>'apiKind'='Deployment' AND guard->>'mode'='running' AND target->'lifecycleGeneration'=guard->'lifecycleGeneration'
        AND effect_input#>>'{admittedRuntime,provider}'=CASE WHEN allocation.component='harness' THEN 'occ/kubernetes-gvisor' ELSE 'occ/kubernetes-gateway' END
        AND ((effect_input->>'action'='reserve-inert' AND predicate->>'kind'='expected-absent' AND preparation->>'kind'='nonmutating')
          OR (effect_input->>'action'='materialize' AND predicate->>'kind'='expected-object')));
    ELSIF effect_input->>'kind'='set-route' THEN
      PERFORM occ.runtime_preparation_require(provider->>'apiKind' IN ('Service','HTTPRoute','EndpointSlice') AND predicate->>'kind'='expected-object'
        AND child#>>'{effect,effectKind}'=CASE WHEN effect_input#>>'{desiredRoute,kind}'='active' THEN 'route-active' ELSE 'route-inactive' END);
      IF effect_input#>>'{desiredRoute,kind}'='active' THEN
        PERFORM occ.runtime_preparation_require(effect_input#>'{desiredRoute,selectedTarget}'=target AND effect_input#>'{desiredRoute,binding,component}'=target->'component'
          AND guard->>'mode'='running' AND target->'lifecycleGeneration'=guard->'lifecycleGeneration'
          AND occ.runtime_preparation_writer_ref(effect_input#>'{desiredRoute,priorWriterEvidence}',scope,guard));
      END IF;
    ELSE
      -- Protective stop/sealer operations require their separate non-preparation owner.
      PERFORM occ.runtime_preparation_require(false);
    END IF;
  ELSIF kind='retain-binding' THEN
    proposal:=request->'proposal'; operation:=request->'operation'; proposal_bytes:=occ.runtime_preparation_canonical(proposal-'requestRef');
    PERFORM occ.runtime_preparation_require(octet_length(occ.runtime_preparation_canonical(proposal))<=65536
      AND proposal->'target'=target AND proposal->'responsibilityRef'=guard#>'{responsibility,responsibilityRef}'
      AND proposal->'expectedResponsibilityVersion'=guard#>'{responsibility,responsibilityVersion}' AND proposal->'expectedLifecycleGeneration'=target->'lifecycleGeneration'
      AND proposal#>'{binding,component}'=target->'component' AND proposal->'expectedBindingVersion'='null'::jsonb
      AND (proposal->>'expectedAssignmentRecordVersion')::bigint=(SELECT coalesce(max(assignment_record_version),1) FROM occ.runtime_authority_operations WHERE assignment_ref=NEW.assignment_ref)
      AND operation=jsonb_build_object('schemaVersion',1,'installationId',NEW.installation_id,'namespaceId',NEW.namespace_id,'agentId',NEW.agent_id,
        'operationRef',proposal->'operationRef','operationKind','bind','canonicalPayloadDigest','sha256:'||encode(sha256(convert_to(proposal_bytes,'UTF8')),'hex'),'requestRef',proposal->'requestRef')
      AND NOT EXISTS(SELECT 1 FROM occ.runtime_preparation_operations WHERE preparation_ref=NEW.preparation_ref AND operation_kind='retain-binding'));
    PERFORM occ.runtime_preparation_require(EXISTS(SELECT 1 FROM occ.runtime_preparation_operations h WHERE h.preparation_ref=NEW.preparation_ref AND h.operation_kind='retain-child'
      AND h.canonical_request::jsonb#>>'{child,request,kind}'='create' AND h.canonical_request::jsonb#>>'{child,request,action}'='materialize'
      AND h.canonical_request::jsonb#>'{child,guard}'=guard AND h.canonical_request::jsonb#>>'{child,predicate,kind}'='expected-object'
      AND h.canonical_request::jsonb#>'{child,predicate,uid}'=proposal#>'{binding,deploymentUid}'
      AND h.canonical_request::jsonb#>'{child,providerTarget,clusterRef}'=proposal#>'{binding,clusterRef}'
      AND h.canonical_request::jsonb#>'{child,providerTarget,kubernetesNamespaceUid}'=proposal#>'{binding,kubernetesNamespaceUid}'
      AND h.canonical_request::jsonb#>'{child,request,admittedRuntime,provider}'=proposal#>'{binding,provider}'
      AND h.canonical_request::jsonb#>>'{child,request,admittedRuntime,runtimeProfileRef}'=allocation.runtime_profile_ref
      AND h.canonical_request::jsonb#>'{child,request,admittedRuntime,runtimeProfileDigest}'=proposal#>'{binding,profileDigests,runtime}'
      AND h.canonical_request::jsonb#>'{child,request,admittedRuntime,configurationDigest}'=proposal#>'{binding,admittedConfigurationDigest}'));
  ELSIF kind='supersede-plan' THEN
    PERFORM occ.runtime_preparation_require((selected_guard->>'gateVersion')::numeric=(guard->>'gateVersion')::numeric+1
      AND (selected_guard->>'requestedFenceEpoch')::numeric>=(guard->>'requestedFenceEpoch')::numeric
      AND selected_guard#>'{responsibility,responsibilityRef}'=guard#>'{responsibility,responsibilityRef}'
      AND (selected_guard#>>'{responsibility,responsibilityVersion}')::numeric>=(guard#>>'{responsibility,responsibilityVersion}')::numeric
      AND selected_guard->'planRef'=guard->'planRef' AND (selected_guard->>'planVersion')::numeric=(guard->>'planVersion')::numeric+1
      AND selected_guard->'admittedChildCutoff'=guard->'admittedChildCutoff'
      AND (request->'preparation'=preparation OR (request#>>'{preparation,preparationVersion}')::numeric=(preparation->>'preparationVersion')::numeric+1));
  END IF;
  sequence:=coalesce((previous->>'retainedChildSequence')::bigint,0)+CASE WHEN kind='retain-child' THEN 1 ELSE 0 END;
  expected_record:=jsonb_build_object('schemaVersion',1,'operationRef',NEW.operation_ref,'preparationRef',NEW.preparation_ref,'target',target,'kind',kind,
    'localVersion',NEW.local_version,'retainedChildSequence',sequence,'localState',CASE WHEN kind='close' THEN request->>'reason' ELSE 'open' END,
    'guard',selected_guard,'canonicalRequest',NEW.canonical_request,'requestDigest','sha256:'||encode(sha256(convert_to(NEW.canonical_request,'UTF8')),'hex'),'attribution',NEW.record->'attribution');
  PERFORM occ.runtime_preparation_require(NEW.record=expected_record AND NEW.child_effect_ref IS NOT DISTINCT FROM CASE WHEN kind='retain-child' THEN request#>>'{child,effect,effectRef}' END
    AND NEW.binding_operation_ref IS NOT DISTINCT FROM CASE WHEN kind='retain-binding' THEN request#>>'{operation,operationRef}' END);
  RETURN NEW;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow OR invalid_datetime_format THEN
  RAISE EXCEPTION 'runtime preparation persisted data invalid' USING ERRCODE='23514';
END;
$$;
